BEGIN;
INSERT INTO permission_catalog(permission_code,domain,risk_class,sod_class) VALUES('FIXED_ASSET.REGISTER.REVIEW','FIXED_ASSET','HIGH','REVIEWER'),('FIXED_ASSET.REGISTER.VIEW','FIXED_ASSET','LOW','VIEWER') ON CONFLICT(permission_code) DO UPDATE SET active=true,version=permission_catalog.version+1,effective_to=NULL;
CREATE TABLE fixed_asset_register_evidence(fixed_asset_register_evidence_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenant,entity_id uuid NOT NULL,capitalization_proposal_id uuid NOT NULL,source_document_id uuid NOT NULL,source_payload_hash text NOT NULL CHECK(source_payload_hash~'^sha256:[0-9a-f]{64}$'),asset_tag text NOT NULL CHECK(length(btrim(asset_tag)) BETWEEN 1 AND 100),asset_class text NOT NULL CHECK(length(btrim(asset_class)) BETWEEN 1 AND 128),currency char(3) NOT NULL CHECK(currency~'^[A-Z]{3}$'),cost_basis numeric(20,4) NOT NULL CHECK(cost_basis>0),salvage_value numeric(20,4) NOT NULL CHECK(salvage_value>=0 AND salvage_value<cost_basis),placed_in_service_date date NOT NULL,useful_life_months integer NOT NULL CHECK(useful_life_months BETWEEN 1 AND 600),depreciation_method text NOT NULL CHECK(depreciation_method='STRAIGHT_LINE'),depreciation_convention text NOT NULL CHECK(depreciation_convention='FULL_MONTH'),asset_account_code text NOT NULL,accumulated_depreciation_account_code text NOT NULL,depreciation_expense_account_code text NOT NULL,member_trace jsonb NOT NULL,status text NOT NULL CHECK(status='ACTIVE'),reviewed_by text NOT NULL,review_reason text NOT NULL CHECK(length(btrim(review_reason)) BETWEEN 8 AND 2000),register_evidence_hash text NOT NULL CHECK(register_evidence_hash~'^sha256:[0-9a-f]{64}$'),reviewed_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,entity_id,capitalization_proposal_id),UNIQUE(tenant_id,entity_id,asset_tag),UNIQUE(tenant_id,entity_id,register_evidence_hash),FOREIGN KEY(tenant_id,entity_id) REFERENCES entity(tenant_id,entity_id),FOREIGN KEY(tenant_id,entity_id,capitalization_proposal_id) REFERENCES ai_invoice_capitalization_proposal(tenant_id,entity_id,ai_invoice_capitalization_proposal_id),FOREIGN KEY(tenant_id,entity_id,source_document_id) REFERENCES source_document(tenant_id,entity_id,source_document_id),CHECK(asset_account_code<>accumulated_depreciation_account_code AND asset_account_code<>depreciation_expense_account_code AND accumulated_depreciation_account_code<>depreciation_expense_account_code));
ALTER TABLE fixed_asset_register_evidence ENABLE ROW LEVEL SECURITY;CREATE POLICY fixed_asset_register_evidence_scope ON fixed_asset_register_evidence USING(tenant_id=refs_current_tenant() AND refs_entity_allowed(entity_id));CREATE TRIGGER fixed_asset_register_evidence_append_only BEFORE UPDATE OR DELETE ON fixed_asset_register_evidence FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE FUNCTION refs_read_ai_fixed_asset_depreciation_source(p_tenant uuid,p_entity uuid,p_period uuid) RETURNS SETOF jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ BEGIN PERFORM refs_assert_scope(p_tenant,p_entity,'AI.ANALYSIS.EXPLAIN');RETURN QUERY WITH p AS (SELECT period_id,period_code,starts_on,ends_on FROM accounting_period WHERE tenant_id=p_tenant AND entity_id=p_entity AND period_id=p_period AND ledger_code='PRIMARY'),calc AS (SELECT r.*,p.*,round((r.cost_basis-r.salvage_value)/r.useful_life_months,4) monthly,greatest(0,least(r.useful_life_months,((extract(year from p.ends_on)::int-extract(year from r.placed_in_service_date)::int)*12+extract(month from p.ends_on)::int-extract(month from r.placed_in_service_date)::int+1))) elapsed FROM fixed_asset_register_evidence r CROSS JOIN p WHERE r.tenant_id=p_tenant AND r.entity_id=p_entity AND r.status='ACTIVE') SELECT jsonb_build_object('period_id',period_id,'period_code',period_code,'fixed_asset_register_evidence_id',fixed_asset_register_evidence_id,'source_document_id',source_document_id,'source_payload_hash',source_payload_hash,'capitalization_proposal_id',capitalization_proposal_id,'register_evidence_hash',register_evidence_hash,'asset_tag',asset_tag,'asset_class',asset_class,'depreciation_method',depreciation_method,'depreciation_convention',depreciation_convention,'placed_in_service_date',to_char(placed_in_service_date,'YYYY-MM-DD'),'useful_life_months',useful_life_months,'currency',currency,'cost_basis',to_char(cost_basis,'FM999999999999990.0000'),'salvage_value',to_char(salvage_value,'FM999999999999990.0000'),'depreciable_basis',to_char(cost_basis-salvage_value,'FM999999999999990.0000'),'expected_period_depreciation',to_char(CASE WHEN starts_on>=(placed_in_service_date-date_part('day',placed_in_service_date)::int+1) AND elapsed BETWEEN 1 AND useful_life_months THEN least(monthly,(cost_basis-salvage_value)-monthly*(elapsed-1)) ELSE 0 END,'FM999999999999990.0000'),'expected_accumulated_depreciation',to_char(least(cost_basis-salvage_value,monthly*elapsed),'FM999999999999990.0000'),'expected_net_book_value',to_char(cost_basis-least(cost_basis-salvage_value,monthly*elapsed),'FM999999999999990.0000'),'asset_account_code',asset_account_code,'accumulated_depreciation_account_code',accumulated_depreciation_account_code,'depreciation_expense_account_code',depreciation_expense_account_code,'status',status) FROM calc ORDER BY asset_tag;END;$$;
REVOKE ALL ON fixed_asset_register_evidence FROM PUBLIC,refs_app;REVOKE EXECUTE ON FUNCTION refs_read_ai_fixed_asset_depreciation_source(uuid,uuid,uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION refs_read_ai_fixed_asset_depreciation_source(uuid,uuid,uuid) TO refs_app;
COMMIT;
